package com.hbm.machine.reactor.pile.core;
import com.hbm.api.tool.ToolableBlock;import net.minecraft.core.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.material.MapColor;
/** Original full-volume source-bounded assembly using a hand drill, with source probe and placement order. */
public final class PileBrickBlock extends Block implements ToolableBlock {
 public PileBrickBlock(){super(Properties.of().mapColor(MapColor.STONE).strength(5,6).sound(SoundType.METAL).requiresCorrectToolForDrops());}
 @Override public int getFlammability(BlockState state,BlockGetter level,BlockPos pos,Direction face){return 5;}@Override public int getFireSpreadSpeed(BlockState state,BlockGetter level,BlockPos pos,Direction face){return 30;}
 @Override public boolean onScrew(Level level,Player player,BlockPos pos,Direction side,float hx,float hy,float hz,ToolType tool){if(tool!=ToolType.HAND_DRILL||side.getAxis()==Direction.Axis.Y)return false;if(level.isClientSide)return true;var dir=PileDirection.of(side.getOpposite());var leftDir=dir.getRotation(PileDirection.DOWN);int x=pos.getX(),y=pos.getY(),z=pos.getZ(),up=0,down=0,left=0,right=0,depth=0;
  for(int i=1;i<=14;i++){if(!level.getBlockState(pos.above(i)).is(this))break;up=i;}for(int i=1;i<=15-up-1;i++){if(!level.getBlockState(pos.below(i)).is(this))break;down=i;}
  for(int i=1;i<=14;i++){if(!level.getBlockState(pos.offset(leftDir.offsetX*i,0,leftDir.offsetZ*i)).is(this))break;left=i;}for(int i=1;i<=15-left-1;i++){if(!level.getBlockState(pos.offset(-leftDir.offsetX*i,0,-leftDir.offsetZ*i)).is(this))break;right=i;}
  for(int i=1;i<=15;i++){if(!level.getBlockState(pos.offset(dir.offsetX*i,0,dir.offsetZ*i)).is(this))break;depth=i;}
  if(up+down+1<5){PileErrors.send(level,x,y+up,z,"height",player);PileErrors.send(level,x,y-down,z,"height",player);return true;}if(left+right+1<5){PileErrors.send(level,x+leftDir.offsetX*left,y,z+leftDir.offsetZ*right,"width",player);PileErrors.send(level,x-leftDir.offsetX*right,y,z-leftDir.offsetZ*right,"width",player);return true;}if(depth+1<5){PileErrors.send(level,x+dir.offsetX*depth,y,z+dir.offsetZ*depth,"depth",player);return true;}if(up==0||down==0||left==0||right==0){PileErrors.send(level,x,y,z,"core_edge",player);return true;}
  for(int h=-down;h<=up;h++)for(int v=-left;v<=right;v++)for(int d=0;d<=depth;d++){var at=pos.offset(-leftDir.offsetX*v+dir.offsetX*d,h,-leftDir.offsetZ*v+dir.offsetZ*d);if(!level.getBlockState(at).is(this)){PileErrors.send(level,at.getX(),at.getY(),at.getZ(),"missing",player);return true;}}
  // This is one validated final placement, never an on-tick proxy expansion.
  for(int h=-down;h<=up;h++)for(int v=-left;v<=right;v++)for(int d=0;d<=depth;d++){var at=pos.offset(-leftDir.offsetX*v+dir.offsetX*d,h,-leftDir.offsetZ*v+dir.offsetZ*d);if(at.equals(pos)){level.setBlock(at,PileCoreContent.BODY.get().defaultBlockState().setValue(PileCoreContent.META,PileBodyBlock.META_CORE),3);if(level.getBlockEntity(at) instanceof TileEntityPileCore core){core.orientation=TileEntityPileCore.PileOrientation.getOrientation(dir);core.setupSize(up,down,left,right,depth+1);core.setChanged();}}else{int edge=(h==-down||h==up?1:0)+(v==-left||v==right?1:0)+(d==0||d==depth?1:0);level.setBlock(at,PileCoreContent.BODY.get().defaultBlockState().setValue(PileCoreContent.META,edge>1?PileBodyBlock.META_EDGE:PileBodyBlock.META_DUMMY),3);if(level.getBlockEntity(at) instanceof TileEntityPileBaseMK2 part)part.setCore(x,y,z);}}
 return true;}
}
